  Lemma AImplBlockC_fs_call : forall LF k ff fp m0 m1 m2 LB b I slo shi',
    as_RFS H LF m0 -> fresh_frame H LF k ff fp -> aceil <= slo ->
    AImplBlockC LB m1 b I -> fsobj H LF b SZ_SPCI_IMPL -> (0 < im_vcap I -> fsobj H LF (im_vb I) (8 * im_vcap I)) ->
    munch (fs_W5 H slo shi' fp ff k) m1 m2 -> wmono asegs m1 m2 -> AImplBlockC LB m2 b I.
  Proof.
    intros LF k ff fp m0 m1 m2 LB b I slo shi' RF FF CEIL P FO FOV MU WM.
    pose proof P as (p & j7 & IN & RB & _ & _ & _ & _ & _ & _ & ST & _).
    pose proof (rblock_bounds _ _ RB) as (B1 & B2 & B3 & B4 & B5 & B6). pose proof RB as (_ & _ & _ & AP & _).
    eapply AImplBlockC_transport; [exact P| exact MU| exact WM| | | |].
    - eapply (fsobj_disjoint H HH); [exact RF| exact FO| exact FF| exact B1| exact B2| exact B3| exact AP| left; lia].
    - intros POS. destruct ST as [[Z0 _]|(q & junk & INq & RBq & _)]; [lia|].
      pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6). pose proof RBq as (_ & _ & _ & APq & _).
      eapply (fsobj_disjoint H HH); [exact RF| exact (FOV POS)| exact FF| exact C1| exact C2| exact C3| exact APq| left; lia].
    - eapply (fsobj_disjoint_sh H HH); [exact RF| exact FO| exact FF| exact B1| exact B2| exact B3| exact CEIL].
    - intros POS. destruct ST as [[Z0 _]|(q & junk & INq & RBq & _)]; [lia|].
      pose proof (rblock_bounds _ _ RBq) as (C1 & C2 & C3 & C4 & C5 & C6).
      eapply (fsobj_disjoint_sh H HH); [exact RF| exact (FOV POS)| exact FF| exact C1| exact C2| exact C3| exact CEIL].
  Qed.
